        r = sd_journal_seek_head(j); /* seek to oldest */
        if (r < 0)
                return r;

        r = sd_journal_next(j);      /* read the oldest entry */
        if (r < 0)
                return r;

        sd_journal_flush_matches(j);
        return r > 0;
